// The worker-mobile, -binary, -ai and -fuzz manifests (workers/<family>/
// tools.d) are parsed against REAL tool output. Each fixture in
// testdata/manifests/<family>-*.json was generated by running the
// manifest's command in the family image built from this repository, with
// the worker's workspace layout (/work/fixture/...):
//
//   - mobile (docker run --network none): pathos-mobile mobsfscan|apkleaks|
//     quark|checks on workers/mobile/test/apk/pathos-test.apk (built from
//     workers/mobile/test/apk with build.sh), and checks on an IPA built with
//     workers/mobile/test/ipa/build_ipa.py (mobile-checks-ipa.json)
//   - binary (--network none): pathos-binary yara|capa|cve-bin-tool on a
//     directory with the ELF built from workers/binary/test/sample.c and an
//     EICAR test file; CVE Binary Tool used a database built with
//     `cve-bin-tool -u now -n json-mirror` (NVD JSON 2.0 mirror) on
//     2026-11-19, copied into the cache volume
//   - ai: pathos-ai modelscan on a directory with a pickle whose __reduce__
//     calls os.system (--network none); garak and promptfoo against
//     workers/ai/test/stub_llm.py on an internal docker network (no other
//     route), with GARAK_PROMPT_CAP=8 to keep the fixture small
//   - fuzz (--network none): pathos-fuzz go|atheris on workers/fuzz/test/
//     sample (a Go fuzz target and an Atheris harness with planted bugs),
//     FUZZ_SECONDS=20

type familyCase struct {
	family, manifest, fixture, key, category, parser string
	targets                                          []string
	network                                          string
	intrusive                                        bool
	rules                                            []string // rule ids that must be found
	min                                              int
	paths                                            []string // file paths that must be found
}

