func loadFamilySpec(t *testing.T, family, file string) PluginDef {
	t.Helper()
	raw, err := os.ReadFile(filepath.Join("../../../workers", family, "tools.d", file))
	if err != nil {
		t.Fatal(err)
	}
	d, err := decodeManifestSpec(raw, true)
	if err != nil {
		t.Fatalf("%s/%s: %v", family, file, err)
	}
	return d
}

func TestFamilyManifestsParseRealOutput(t *testing.T) {
	for _, c := range familyCases {
		t.Run(c.fixture, func(t *testing.T) {
			d := loadFamilySpec(t, c.family, c.manifest)
			if d.Key() != c.key || d.Category != c.category || d.ToolParser().String() != c.parser || !d.FirstParty || d.Family != c.family {
				t.Fatalf("manifest: key %s category %s parser %s family %s", d.Key(), d.Category, d.ToolParser().String(), d.Family)
			}
			if !slices.Equal(d.Targets, c.targets) || d.Network != c.network || d.Intrusive != c.intrusive {
				t.Errorf("targets %v network %s intrusive %v", d.Targets, d.Network, d.Intrusive)
			}
			if d.LicenseSPDX == "" || len(d.ScanTypes) == 0 || d.DefaultEnabled {
				t.Errorf("licence, scan types, off by default: %+v", d)
			}
			sc, ok := scanners.Lookup(c.key)
			if !ok || !sc.AdapterAvailable || sc.Family != c.family || !scanners.ManifestRouted(c.key) || sc.License != d.LicenseSPDX {
				t.Errorf("catalog entry: %+v", sc)
			}
			if !slices.Equal(scanners.TargetsOf(sc), c.targets) || sc.Network != c.network || sc.Intrusive != c.intrusive {
				t.Errorf("catalog targets %v network %s intrusive %v", scanners.TargetsOf(sc), sc.Network, sc.Intrusive)
			}
			for _, st := range d.ScanTypes {
				if !slices.Contains(scanners.ScanTypesOf(c.key), st) {
					t.Errorf("scan type %s does not list %s", st, c.key)
				}
			}
			raw, err := os.ReadFile(filepath.Join("testdata", "manifests", c.fixture))
			if err != nil {
				t.Fatal(err)
			}
			fs, err := scanners.ParseToolOutput(d.Key(), d.ToolParser(), raw)
			if err != nil {
				t.Fatalf("parse: %v", err)
			}
			if len(fs) < c.min {
				t.Fatalf("findings: %d, want at least %d", len(fs), c.min)
			}
			var rules, paths []string
			fps := map[string]bool{}
			for _, f := range fs {
				rules = append(rules, f.RuleID)
				paths = append(paths, f.FilePath)
				if f.ScannerKey != c.key || f.Category != c.category || f.Fingerprint == "" || f.Title == "" {
					t.Errorf("finding: %+v", f)
				}
				if strings.HasPrefix(f.FilePath, "/") || strings.Contains(f.FilePath, "work/") {
					t.Errorf("path is not relative to the scanned directory: %q", f.FilePath)
				}
				if scanners.SeverityRank(f.Severity) == 0 && f.Severity != "info" {
					t.Errorf("severity %q", f.Severity)
				}
				fps[f.Fingerprint] = true
				loc, err := scanners.LocateToolOutput(d.Key(), d.ToolParser(), raw, f.Fingerprint)
				if err != nil || loc == nil || len(loc.Raw) == 0 {
					t.Errorf("locate %s: %v", f.RuleID, err)
				}
			}
			if len(fps) != len(fs) {
				t.Errorf("fingerprints are distinct: %d of %d", len(fps), len(fs))
			}
			for _, r := range c.rules {
				if !slices.Contains(rules, r) {
					t.Errorf("rule %s not found in %v", r, rules)
				}
			}
			for _, p := range c.paths {
				if !slices.Contains(paths, p) {
					t.Errorf("path %s not found in %v", p, paths)
				}
			}
		})
	}
}

func TestFamilyFindingDetails(t *testing.T) {
	parse := func(family, manifest, fixture string) []scanners.Finding {
		d := loadFamilySpec(t, family, manifest)
		raw, err := os.ReadFile(filepath.Join("testdata", "manifests", fixture))
		if err != nil {
			t.Fatal(err)
		}
		fs, err := scanners.ParseToolOutput(d.Key(), d.ToolParser(), raw)
		if err != nil {
			t.Fatal(err)
		}
		return fs
	}
	// Mobile checks: severity, CWE and one finding per exported component.
	exported := 0
	for _, f := range parse("mobile", "mobile-app-checks.yaml", "mobile-checks-apk.json") {
		switch f.RuleID {
		case "ANDROID-DEBUGGABLE":
			if f.Severity != "high" || !slices.Contains(f.CWE, "CWE-489") {
				t.Errorf("debuggable: %+v", f)
			}
		case "ANDROID-EXPORTED-ACTIVITY", "ANDROID-EXPORTED-SERVICE", "ANDROID-EXPORTED-PROVIDER":
			exported++
		}
	}
	if exported != 3 {
		t.Errorf("exported components: %d", exported)
	}
	// APKLeaks: secret values are never in titles or descriptions.
	for _, f := range parse("mobile", "apkleaks.yaml", "mobile-apkleaks.json") {
		if strings.Contains(f.Title+f.Description, "pathosTestApiKeyValue0123456789abcd") {
			t.Errorf("unredacted secret: %+v", f)
		}
	}
	// Quark: confidence 100% is high.
	for _, f := range parse("mobile", "quark-engine.yaml", "mobile-quark.json") {
		if f.Severity != "high" || !strings.Contains(f.Description, "MainActivity") {
			t.Errorf("quark: %+v", f)
		}
	}
	// CVE Binary Tool: SCA-style findings with package, version, CVE, CVSS.
	cves := parse("binary", "cve-bin-tool.yaml", "binary-cve-bin-tool.json")
	curl := 0
	for _, f := range cves {
		if f.CVE == "" || f.PackageName == "" || f.PackageVersion == "" || f.CVSS == nil {
			t.Errorf("cve-bin-tool: %+v", f)
		}
		if f.PackageName == "haxx/libcurl" && f.PackageVersion == "7.29.0" {
			curl++
		}
	}
	if curl < 20 {
		t.Errorf("libcurl 7.29.0 CVEs: %d", curl)
	}
	// capa: malware-typical capabilities are medium, others low or info.
	for _, f := range parse("binary", "capa.yaml", "binary-capa.json") {
		if f.RuleID == "create reverse shell on Linux" && f.Severity != "medium" {
			t.Errorf("reverse shell: %s", f.Severity)
		}
	}
	// Fuzzing: the crash is located at the crashing line and the reproducer
	// is kept in the stored report.
	d := loadFamilySpec(t, "fuzz", "go-fuzz.yaml")
	raw, _ := os.ReadFile(filepath.Join("testdata", "manifests", "fuzz-go.json"))
	fs := parse("fuzz", "go-fuzz.yaml", "fuzz-go.json")
	if len(fs) != 1 || fs[0].StartLine == nil || *fs[0].StartLine != 17 || fs[0].Confidence != "high" || !slices.Contains(fs[0].CWE, "CWE-129") {
		t.Fatalf("go-fuzz: %+v", fs)
	}
	loc, err := scanners.LocateToolOutput(d.Key(), d.ToolParser(), raw, fs[0].Fingerprint)
	if err != nil {
		t.Fatal(err)
	}
	var rec struct {
		Reproducer string `json:"reproducer_base64"`
		Size       int    `json:"reproducer_size"`
		SHA256     string `json:"reproducer_sha256"`
	}
	if err := json.Unmarshal(loc.Raw, &rec); err != nil {
		t.Fatal(err)
	}
	repro, err := base64.StdEncoding.DecodeString(rec.Reproducer)
	if err != nil || !strings.HasPrefix(string(repro), "go test fuzz v1\n") || rec.Size != len(repro) || len(rec.SHA256) != 64 {
		t.Errorf("reproducer evidence: %q %+v", repro, rec)
	}
	// The fuzz reports list every target, including those that passed.
	var rep struct {
		Targets []struct {
			Name, Status string
		} `json:"targets"`
	}
	_ = json.Unmarshal(raw, &rep)
	if len(rep.Targets) != 2 || rep.Targets[1].Status != "passed" {
		t.Errorf("targets: %+v", rep.Targets)
	}
}

func TestFamilyManifestsLoad(t *testing.T) {
	// Every family's manifests load as first-party tools once their
	// commands exist (stand-ins here), and the keys are the expected ones.
	want := map[string][]string{
		"mobile": {"apkleaks", "mobile-app-checks", "mobsfscan", "quark-engine"},
		"binary": {"capa", "cve-bin-tool", "yara-x"},
		"ai":     {"garak", "modelscan", "promptfoo"},
		"fuzz":   {"atheris", "go-fuzz"},
	}
	log := slog.New(slog.NewTextHandler(io.Discard, nil))
	for family, keys := range want {
		dir := t.TempDir()
		bin := fakeTool(t, dir)
		conf := filepath.Join(dir, "tools.d")
		_ = os.MkdirAll(conf, 0o755)
		src := filepath.Join("../../../workers", family, "tools.d")
		entries, err := os.ReadDir(src)
		if err != nil {
			t.Fatal(err)
		}
		for _, e := range entries {
			raw, _ := os.ReadFile(filepath.Join(src, e.Name()))
			var cmd string
			for _, l := range strings.Split(string(raw), "\n") {
				if strings.HasPrefix(l, "command: ") {
					cmd = strings.TrimPrefix(l, "command: ")
				}
			}
			_ = os.WriteFile(filepath.Join(conf, e.Name()), []byte(strings.Replace(string(raw), "command: "+cmd, "command: "+bin, 1)), 0o644)
		}
		var got []string
		for _, d := range LoadToolManifests(conf, log) {
			got = append(got, d.Key())
		}
		slices.Sort(got)
		if !slices.Equal(got, keys) {
			t.Errorf("%s: %v", family, got)
		}
	}
}

func TestLLMEndpointAndMobileTargets(t *testing.T) {
	base := "name: x\ncategory: ai\ncommand: /bin/true\n"
	for _, c := range []struct {
		body string
		ok   bool
	}{
		{base + "targets: [llm-endpoint]\nnetwork: target\nintrusive: true\nargs: [\"{llm_target}\", \"{output}\"]\n", true},
		{base + "targets: [llm-endpoint]\nargs: [\"{target_url}\", \"{output}\"]\n", false}, // the endpoint file is required
		{base + "targets: [mobile-app]\nargs: [\"{artifact}\", \"{output}\"]\n", true},
		{base + "targets: [repository]\nargs: [\"{source}\", \"{llm_target}\", \"{output}\"]\n", true},
	} {
		if _, err := decodeManifestSpec([]byte(c.body), false); (err == nil) != c.ok {
			t.Errorf("%q: %v", c.body, err)
		}
	}
	d, _ := decodeManifestSpec([]byte(base+"targets: [llm-endpoint]\nnetwork: target\nintrusive: true\nargs: [\"{llm_target}\", \"{target_url}\", \"{output}\"]\n"), false)
	if !d.RunsOn("llm-endpoint") || d.RunsOn("url") || d.RunsOn("") || d.RunsOn("artifact") {
		t.Error("llm-endpoint RunsOn")
	}
	got := (pluginTool{def: d}).expand(d.Args, RunInput{Out: "/o", TargetFile: "/t/llm-target.json",
		Target: &JobTarget{Kind: "llm-endpoint", Reference: "https://llm.test/v1/chat/completions"}}, "/tmp/x")
	if strings.Join(got, " ") != "/t/llm-target.json https://llm.test/v1/chat/completions /o" {
		t.Errorf("expand: %v", got)
	}
	// Intrusive LLM tools need the intrusive testing flag.
	if s, _ := (pluginTool{def: d}).Run(context.Background(), RunInput{Out: "/nonexistent/o", TargetFile: "/t/x",
		Target: &JobTarget{Kind: "llm-endpoint"}}); !strings.Contains(s, "intrusive") {
		t.Errorf("intrusive skip: %q", s)
	}
	m, _ := decodeManifestSpec([]byte(base+"targets: [mobile-app]\nargs: [\"{artifact}\", \"{output}\"]\n"), false)
	if !m.RunsOn("mobile-app") || !m.RunsOn("artifact") || m.RunsOn("") {
		t.Error("mobile-app RunsOn")
	}
	got = (pluginTool{def: m}).expand(m.Args, RunInput{Out: "/o", TargetFile: "/w/target/artifact", Target: &JobTarget{Kind: "mobile-app"}}, "/tmp/x")
	if strings.Join(got, " ") != "/w/target/artifact /o" {
		t.Errorf("expand: %v", got)
	}
	b, _ := decodeManifestSpec([]byte(base+"targets: [binary]\nargs: [\"{artifact}\", \"{output}\"]\n"), false)
	if b.RunsOn("mobile-app") || !b.RunsOn("artifact") {
		t.Error("binary tools run on artifacts, not on mobile app targets")
	}
}

func TestWriteLLMTarget(t *testing.T) {
	p := filepath.Join(t.TempDir(), "llm-target.json")
	for _, c := range []struct {
		tg   JobTarget
		want map[string]string
	}{
		{JobTarget{Kind: "llm-endpoint", Reference: "https://llm.test/v1/chat/completions", Model: "m1", AuthType: "header",
			HeaderName: "Authorization", HeaderValue: "Bearer test-value", RateLimit: 5}, map[string]string{"Authorization": "Bearer test-value"}},
		{JobTarget{Kind: "llm-endpoint", Reference: "https://llm.test/v1", Model: "m2", AuthType: "basic", Username: "u", Password: "p"},
			map[string]string{"Authorization": "Basic dTpw"}},
		{JobTarget{Kind: "llm-endpoint", Reference: "https://llm.test/v1", Model: "m3"}, map[string]string{}},
	} {
		if _, err := writeLLMTarget(&c.tg, p); err != nil {
			t.Fatal(err)
		}
		st, _ := os.Stat(p)
		if st.Mode().Perm() != 0o600 {
			t.Errorf("mode %v", st.Mode())
		}
		raw, _ := os.ReadFile(p)
		var lt LLMTarget
		if err := json.Unmarshal(raw, &lt); err != nil {
			t.Fatal(err)
		}
		if lt.URL != c.tg.Reference || lt.Model != c.tg.Model || lt.API != "openai-chat" || lt.RateLimit != c.tg.RateLimit {
			t.Errorf("target: %+v", lt)
		}
		if len(lt.Headers) != len(c.want) || (len(c.want) > 0 && lt.Headers["Authorization"] != c.want["Authorization"]) {
			t.Errorf("headers: %v", lt.Headers)
		}
	}
	if !mobilePackage("App.APK") || !mobilePackage("x.ipa") || !mobilePackage("b.aab") || mobilePackage("lib.jar") {
		t.Error("mobilePackage")
	}
}
